## 2️⃣ Core Contracts & Shared Types (`ChatServer.Core`)

```csharp
// ChatServer.Core/Models/ChatMessage.cs
namespace ChatServer.Core.Models;

/// <summary>
/// A single chat message that travels through the system.
/// </summary>
public sealed record ChatMessage
{
    public Guid Id { get; init; } = Guid.NewGuid();
    public string RoomId { get; init; } = default!;
    public string SenderUserId { get; init; } = default!;
    public string SenderDisplayName { get; init; } = default!;
    public string Content { get; init; } = default!;
    public DateTimeOffset SentAt { get; init; } = DateTimeOffset.UtcNow;
}
```

```csharp
// ChatServer.Core/Interfaces/IConnection.cs
namespace ChatServer.Core;

/// <summary>
/// Represents a logical client connection after the handshake.
/// </summary>
public interface IConnection : IAsyncDisposable
{
    /// <summary>Unique identifier for the connection (usually a GUID).</summary>
    string ConnectionId { get; }

    /// <summary>Authenticated user id (populated during handshake).</summary>
    string UserId { get; }

    /// <summary>Display name of the user (optional).</summary>
    string? DisplayName { get; }

    /// <summary>Send a raw UTF‑8 text payload to the client.</summary>
    Task SendAsync(string payload, CancellationToken ct = default);

    /// <summary>Raised when the client sends a line of text (after framing).</summary>
    event Func<IConnection, string, Task> ReceivedAsync;
}
```

```csharp
// ChatServer.Core/Interfaces/IConnectionManager.cs
namespace ChatServer.Core;

/// <summary>
/// Accepts TCP connections, performs a handshake, and maintains keep‑alive heartbeats.
/// </summary>
public interface IConnectionManager : IAsyncDisposable
{
    /// <summary>Starts listening for incoming sockets.</summary>
    Task StartAsync(CancellationToken ct = default);

    /// <summary>Raised each time a new logical connection is established.</summary>
