// ChatServer.Core/Interfaces/IRoomManager.cs
namespace ChatServer.Core;

/// <summary>
/// Manages logical chat rooms, membership, permissions and broadcasting.
/// </summary>
public interface IRoomManager
{
    /// <summary>Create a new room (or return existing).</summary>
    Task<Room> GetOrCreateRoomAsync(string roomId, CancellationToken ct = default);

    /// <summary>Join a user to a room with a specific role.</summary>
    Task JoinRoomAsync(string roomId, IConnection connection, Role role, CancellationToken ct = default);

    /// <summary>Leave a room (removes the connection from the member list).</summary>
    Task LeaveRoomAsync(string roomId, IConnection connection, CancellationToken ct = default);

    /// <summary>Broadcast a message to all members of a room (except the sender, if you wish).</summary>
    Task BroadcastAsync(ChatMessage message, CancellationToken ct = default);
}
