## 3️⃣ TCP Connection Manager (`ChatServer.Tcp`)

### 3.1 Handshake & Heartbeat Protocol (text‑based)

```
C: HELLO <UserId> <DisplayName>
S: WELCOME <ConnectionId>
C: PING
S: PONG
...
```

All other messages are just raw UTF‑8 lines that will be routed to the `RoomManager`.

### 3.2 Implementation

```csharp
// ChatServer.Tcp/TcpConnectionManager.cs
using System.Buffers;
using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;
using System.Text;
using ChatServer.Core;
using ChatServer.Core.Models;

namespace ChatServer.Tcp;

/// <summary>
/// Listens on a TCP endpoint, performs a simple text handshake and
/// maintains a per‑connection keep‑alive (ping/pong) timer.
/// </summary>
public sealed class TcpConnectionManager : IConnectionManager
{
    private readonly IPEndPoint _listenEndPoint;
    private readonly TimeSpan _keepAliveInterval;
    private readonly TimeSpan _keepAliveTimeout;
    private readonly CancellationTokenSource _cts = new();
    private readonly ConcurrentDictionary<string, TcpConnection> _connections = new();

    public event Func<IConnection, Task>? ConnectionEstablished;

    public TcpConnectionManager(
        IPEndPoint listenEndPoint,
        TimeSpan? keepAliveInterval = null,
        TimeSpan? keepAliveTimeout = null)
    {
        _listenEndPoint = listenEndPoint;
        _keepAliveInterval = keepAliveInterval ?? TimeSpan.FromSeconds(15);
        _keepAliveTimeout = keepAliveTimeout ?? TimeSpan.FromSeconds(45);
    }

    public async Task StartAsync(CancellationToken ct = default)
    {
        var linked = CancellationTokenSource.CreateLinkedTokenSource(ct, _cts.Token);
        var listener = new TcpListener(_listenEndPoint);
        listener.Start();

        try
        {
            while (!linked.Token.IsCancellationRequested)
            {
                var socket = await listener.AcceptSocketAsync(linked.Token).ConfigureAwait(false);
                _ = HandleSocketAsync(socket, linked.Token); // fire‑and‑forget
            }
        }
        finally
        {
            listener.Stop();
        }
    }

    private async Task HandleSocketAsync(Socket socket, CancellationToken ct)
    {
        var networkStream = new NetworkStream(socket, ownsSocket: true);
        var reader = new StreamReader(networkStream, Encoding.UTF8);
        var writer = new StreamWriter(networkStream, Encoding.UTF8) { AutoFlush = true };

        // 1️⃣ Handshake ---------------------------------------------------------
        // Expect: "HELLO <UserId> <DisplayName>"
        var helloLine = await reader.ReadLineAsync(ct).ConfigureAwait(false);
        if (helloLine == null || !helloLine.StartsWith("HELLO "))
        {
            await writer.WriteLineAsync("ERROR Invalid handshake", ct).ConfigureAwait(false);
            return;
        }

        var parts = helloLine.Split(' ', 3, StringSplitOptions.RemoveEmptyEntries);
        var userId = parts.Length > 1 ? parts[1] : Guid.NewGuid().ToString();
        var displayName = parts.Length > 2 ? parts[2] : null;

        var connectionId = Guid.NewGuid().ToString();
        var connection = new TcpConnection(connectionId, userId, displayName, reader, writer, _keepAliveInterval, _keepAliveTimeout, RemoveConnection);
        _connections[connectionId] = connection;

        // Send welcome
        await writer.WriteLineAsync($"WELCOME {connectionId}", ct).ConfigureAwait(false);

        // Raise event for the rest of the system
        if (ConnectionEstablished != null)
            await ConnectionEstablished.Invoke(connection).ConfigureAwait(false);

        // 2️⃣ Start the per‑connection processing loop (including heartbeat)
        await connection.StartAsync(ct).ConfigureAwait(false);
    }

    private void RemoveConnection(string connectionId)
    {
        _connections.TryRemove(connectionId, out _);
    }

    public async ValueTask DisposeAsync()
    {
        _cts.Cancel();
        foreach (var conn in _connections.Values)
            await conn.DisposeAsync().ConfigureAwait(false);
        _cts.Dispose();
    }

    // -----------------------------------------------------------------------
    // Nested class representing a single logical connection
    // -----------------------------------------------------------------------
    private sealed class TcpConnection : IConnection
    {
        private readonly StreamReader _reader;
        private readonly StreamWriter _writer;
        private readonly TimeSpan _pingInterval;
        private readonly TimeSpan _pingTimeout;
        private readonly Action<string> _onDispose;
        private readonly CancellationTokenSource _cts = new();

        private DateTime _lastPong = DateTime.UtcNow;

        public TcpConnection(
            string connectionId,
            string userId,
            string? displayName,
            StreamReader reader,
            StreamWriter writer,
            TimeSpan pingInterval,
            TimeSpan pingTimeout,
            Action<string> onDispose)
        {
            ConnectionId = connectionId;
            UserId = userId;
            DisplayName = displayName;
            _reader = reader;
            _writer = writer;
            _pingInterval = pingInterval;
            _pingTimeout = pingTimeout;
            _onDispose = onDispose;
        }

        public string ConnectionId { get; }
        public string UserId { get; }
        public string? DisplayName { get; }

        public event Func<IConnection, string, Task>? ReceivedAsync;

        public async Task SendAsync(string payload, CancellationToken ct = default)
        {
            // Simple line‑based framing
            await _writer.WriteLineAsync(payload, ct).ConfigureAwait(false);
        }

        public async Task StartAsync(CancellationToken externalCt)
        {
            var linked = CancellationTokenSource.CreateLinkedTokenSource(_cts.Token, externalCt);
            var readTask = ProcessIncomingAsync(linked.Token);
            var pingTask = PingLoopAsync(linked.Token);

            await Task.WhenAny(readTask, pingTask).ConfigureAwait(false);
            // If one side exits (e.g., client closed), cancel the other.
            _cts.Cancel();
            await Task.WhenAll(readTask, pingTask).ConfigureAwait(false);
        }

        private async Task ProcessIncomingAsync(CancellationToken ct)
        {
            while (!ct.IsCancellationRequested)
            {
                var line = await _reader.ReadLineAsync(ct).ConfigureAwait(false);
                if (line == null) break; // client closed

                // Heartbeat handling
                if (line.Equals("PING", StringComparison.OrdinalIgnoreCase))
                {
                    await _writer.WriteLineAsync("PONG", ct).ConfigureAwait(false);
                    continue;
